insert into public.vocabulary (language_code, lemma, part_of_speech, meaning_tr, example, example_tr, cefr_level, frequency_rank, source) values ('de', 'essen', 'verb', 'yemek yemek', 'Wir wollen um sieben Uhr essen.', 'Saat yedide yemek yemek istiyoruz.', 'A1', 5, 'seed') on conflict (language_code, lemma, part_of_speech) do update set meaning_tr = excluded.meaning_tr, example = excluded.example, example_tr = excluded.example_tr, cefr_level = excluded.cefr_level, frequency_rank = excluded.frequency_rank;
insert into public.vocabulary (language_code, lemma, part_of_speech, meaning_tr, example, example_tr, cefr_level, frequency_rank, source) values ('de', 'groß', 'adj', 'büyük', 'Das Haus ist sehr groß.', 'Ev çok büyük.', 'A1', 6, 'seed') on conflict (language_code, lemma, part_of_speech) do update set meaning_tr = excluded.meaning_tr, example = excluded.example, example_tr = excluded.example_tr, cefr_level = excluded.cefr_level, frequency_rank = excluded.frequency_rank;
insert into public.vocabulary (language_code, lemma, part_of_speech, meaning_tr, example, example_tr, cefr_level, frequency_rank, source) values ('de', 'glücklich', 'adj', 'mutlu', 'Ich bin heute sehr glücklich.', 'Bugün çok mutluyum.', 'A1', 7, 'seed') on conflict (language_code, lemma, part_of_speech) do update set meaning_tr = excluded.meaning_tr, example = excluded.example, example_tr = excluded.example_tr, cefr_level = excluded.cefr_level, frequency_rank = excluded.frequency_rank;
